'use client';
/**
 * Rive State Machine — reference implementation.
 * Two sample .riv files, each driven only through DOM controls: a character (boolean + trigger inputs, pointer
 * reactions) and a five-star rating (a number input behind a native radio group). The reusable part is
 * `RiveCanvas` (./RiveCanvas.tsx); import it with your own file and controls.
 */
import type { CSSProperties } from 'react';
import { spring, springToLinear, useStudioMotion } from '../../motion';
import type { EffectProps } from '../../types';
import { BirdStage } from './BirdStage';
import { RatingStars } from './RatingStars';
import styles from './styles.module.css';

export { RiveCanvas } from './RiveCanvas';
export type { RiveAlignment, RiveCanvasApi, RiveCanvasProps, RiveFit, RiveRuntime } from './RiveCanvas';

type Params = { scene: string; pointer: boolean; backdrop: string; tint: string };
const SCENES = ['both', 'character', 'rating'] as const;
/** Buttons press in within a frame and spring back on release with a small, toy-like overshoot. */
const RELEASE = springToLinear(spring.pop);
/** Values that change (the rating breakdown) settle on the calmer card spring. */
const SETTLE = springToLinear(spring.settle);
const SPRING_VARS = {
  '--rs-spring': RELEASE.easing,
  '--rs-spring-ms': `${RELEASE.duration}ms`,
  '--rs-settle': SETTLE.easing,
  '--rs-settle-ms': `${SETTLE.duration}ms`,
} as CSSProperties;

export default function RiveStateMachine({ params }: EffectProps<Params>) {
  const { reduced } = useStudioMotion();
  const scene = SCENES.find((s) => s === params.scene) ?? 'both';
  return (
    <div className={styles.root} data-reduced={reduced || undefined} style={SPRING_VARS}>
      <div className={styles.grid} data-scene={scene}>
        {scene !== 'rating' ? <BirdStage index="01" pointer={params.pointer} backdrop={params.backdrop} /> : null}
        {scene !== 'character' ? <RatingStars index={scene === 'both' ? '02' : '01'} tint={params.tint} /> : null}
      </div>
      <p className={styles.credit}>Artwork: birb.riv and rating_animation.riv, Rive’s example files (MIT)</p>
    </div>
  );
}

'use client';
import { useCallback, useEffect, useId, useRef, useState, type CSSProperties, type PointerEvent } from 'react';
import type { DeprecationId } from '@rive-app/canvas-lite';
import { duration as D, useStudioMotion } from '../../motion';
import { useCueSweep } from './cue';
import { RiveCanvas, type RiveCanvasApi } from './RiveCanvas';
import styles from './styles.module.css';

const BIRB = { src: '/rive/birb.riv', artboard: 'birb', stateMachine: 'birb' } as const;
/** birb artboard geometry, in its 600 × 600 units (measured): body spans x 111–486, the eyes sit at y ≈ 200. */
const ART = { size: 600, cx: 299, eyeY: 200, half: 188 };
/** The sample file predates data binding: it is driven by inputs and reports states, which Rive now flags. */
const QUIET: readonly DeprecationId[] = ['state-machine-inputs', 'state-change-events'];
const SAY: Record<string, string> = { idle: 'idling', lookUp: 'looking up', slowDance: 'dancing' };
/** Longest explicit reaction (the look-up runs ≈ 2.8 s): if no state change reports it finished, stop anyway. */
const SAFETY_MS = 4000;

type Props = { index: string; pointer: boolean; backdrop: string };

export function BirdStage({ index, pointer, backdrop }: Props) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const api = useRef<RiveCanvasApi | null>(null);
  const boxRef = useRef<HTMLDivElement>(null);
  const wallRef = useRef<HTMLDivElement>(null);
  const cueRefs = useRef<Record<'dance' | 'look', HTMLElement | null>>({ dance: null, look: null });
  const sweep = useCueSweep(reduced);

  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const [dance, setDance] = useState(false);
  /** Whether the state machine advances. Off by default under reduced motion; Pause/Play always wins. */
  const [playing, setPlaying] = useState(!reduced);
  const [state, setState] = useState('idle');
  const [said, setSaid] = useState({ text: '', n: 0 });

  const paused = !playing;
  const reactive = pointer && !reduced && ready && playing;

  /**
   * Reduced motion: Dance and Look up are explicit, so they play; `settle` marks that Birb should hold still again
   * once it is back to idle (`seen`: a non-idle state has been entered since). Pressing Play clears it.
   */
  const live = useRef({ reduced, settle: false, seen: false, inZone: false });
  live.current.reduced = reduced;
  const timer = useRef<number | undefined>(undefined);
  const clearTimer = () => { if (timer.current !== undefined) { window.clearTimeout(timer.current); timer.current = undefined; } };
  useEffect(() => clearTimer, []);
  const holdStill = () => { clearTimer(); live.current.settle = false; setPlaying(false); };
  /** Play a reaction under reduced motion, then hold still. `seen`: it already left idle (dance → idle). */
  const playThenSettle = (seen: boolean, safetyMs?: number) => {
    clearTimer();
    Object.assign(live.current, { settle: true, seen });
    setPlaying(true);
    // If no state change comes back (file without the expected states), still stop.
    if (safetyMs) timer.current = window.setTimeout(holdStill, safetyMs);
  };

  // Turning reduced motion on or off resets playback to the new default.
  const firstReduced = useRef(reduced);
  useEffect(() => {
    if (firstReduced.current === reduced) return;
    firstReduced.current = reduced;
    clearTimer();
    live.current.settle = false;
    setPlaying(!reduced);
  }, [reduced]);

  // The boolean input mirrors the toggle (also when the file finishes loading after a press).
  useEffect(() => {
    const input = api.current?.input('dance');
    if (input) input.value = dance;
  }, [dance, ready]);

  const say = (text: string) => setSaid((s) => ({ text, n: s.n + 1 }));

  const onStateChange = useCallback((states: string[]) => {
    const s = states[states.length - 1];
    if (!s) return;
    setState(s);
    const l = live.current;
    if (s !== 'idle') { l.seen = true; return; }
    // Back to idle after an explicit reaction: let the blend land, then hold still.
    if (l.reduced && l.settle && l.seen) {
      clearTimer();
      timer.current = window.setTimeout(holdStill, D.slow);
    }
  }, []);

  const toggleDance = () => {
    const next = !dance;
    setDance(next);
    if (!reduced) setPlaying(true);
    else if (next) { if (!playing) playThenSettle(false); } // dances until toggled off or paused
    else if (!playing || live.current.settle) playThenSettle(true, SAFETY_MS); // ease back to idle, then hold
    sweep(cueRefs.current.dance);
  };

  const lookUp = (from: 'button' | 'pointer') => {
    const input = api.current?.input('look up');
    if (from === 'button') {
      if (!reduced) setPlaying(true);
      // Mid-dance the routine resumes after the glance, so only a look-up from idle needs the safety stop.
      else if (!playing || live.current.settle) playThenSettle(false, dance ? undefined : SAFETY_MS);
      say(ready ? 'Birb looks up.' : 'Birb is still loading.');
    }
    input?.fire();
    sweep(cueRefs.current.look);
  };

  const togglePlay = () => {
    clearTimer();
    live.current.settle = false;
    setPlaying(!playing);
    say(playing ? 'Animation paused.' : 'Animation playing.');
  };

  // ── Pointer: Birb looks up when the pointer comes in above its eyes; the back wall's light leans toward it.
  const onPointer = (e: PointerEvent<HTMLDivElement>) => {
    if (!reactive || (e.target as Element).closest('button')) return;
    const box = boxRef.current?.getBoundingClientRect();
    const stage = e.currentTarget.getBoundingClientRect();
    if (!box) return;
    // Fit "contain", aligned bottom-centre: where the artboard lands inside the box.
    const s = Math.min(box.width, box.height) / ART.size;
    const eyeX = box.left + (box.width - ART.size * s) / 2 + ART.cx * s;
    const eyeY = box.top + (box.height - ART.size * s) + ART.eyeY * s;
    const half = ART.half * s;
    const dx = e.clientX - eyeX;
    const dy = eyeY - e.clientY;
    const l = live.current;
    // A cone opening upward from the eye line; leaving needs a margin, so the edge does not flicker.
    const inside = dy > 0 && Math.abs(dx) < half + dy * 0.8;
    const outside = dy < -half * 0.2 || Math.abs(dx) > half * 1.25 + Math.max(0, dy) * 0.8;
    if (inside && !l.inZone) { l.inZone = true; lookUp('pointer'); }
    else if (outside) l.inZone = false;
    if (e.pointerType !== 'touch' && wallRef.current) {
      const nx = ((e.clientX - stage.left) / stage.width) * 2 - 1;
      const ny = ((e.clientY - stage.top) / stage.height) * 2 - 1;
      wallRef.current.style.transform = `translate3d(${(nx * 9).toFixed(2)}%, ${(ny * 5).toFixed(2)}%, 0)`;
    }
  };
  const onPointerLeave = () => {
    live.current.inZone = false;
    if (wallRef.current) wallRef.current.style.transform = '';
  };
  useEffect(() => { if (!reactive && wallRef.current) wallRef.current.style.transform = ''; }, [reactive]);

  const stateWord = failed ? 'unavailable' : !ready ? 'loading' : paused ? 'paused' : (SAY[state] ?? state);
  const hint = reduced
    ? 'Reduced motion: Birb holds still until you press Dance, Look up or Play, then settles again.'
    : pointer
      ? 'Bring the pointer in above Birb’s head and it looks up at you; Look up does the same from the keyboard, Dance toggles the routine.'
      : 'Pointer reactions are off: Dance and Look up drive the state machine.';

  return (
    <section className={styles.panel} aria-labelledby={`${uid}t`} style={{ '--i': 0 } as CSSProperties}>
      <header className={styles.head}>
        <span className={styles.index} aria-hidden="true">{index}</span>
        <h3 id={`${uid}t`} className={styles.title}>Character</h3>
        <span className={styles.status} data-live={(!paused && ready) || undefined}>
          <span className={styles.dot} aria-hidden="true" />
          {stateWord}
        </span>
      </header>

      <div
        className={styles.stage}
        data-backdrop={backdrop}
        data-reactive={reactive || undefined}
        onPointerMove={onPointer}
        onPointerDown={onPointer}
        onPointerLeave={onPointerLeave}
      >
        <div ref={wallRef} className={styles.wall} aria-hidden="true" />
        <div className={styles.floor} aria-hidden="true" />
        <div ref={boxRef} className={styles.birdBox}>
          <RiveCanvas
            className={styles.fill}
            src={BIRB.src}
            artboard={BIRB.artboard}
            stateMachine={BIRB.stateMachine}
            fit="contain"
            alignment="bottomCenter"
            paused={paused}
            quietDeprecations={QUIET}
            label={`Birb, a round blue cartoon bird on a small stage, ${stateWord}`}
            loading={<span className={styles.loadingNote}>loading birb.riv</span>}
            fallback={(
              <div className={styles.birdFallback}>
                <svg viewBox="0 0 120 120" width="88" height="88" aria-hidden="true">
                  <ellipse cx="60" cy="108" rx="40" ry="6" className={styles.fbShadow} />
                  <circle cx="60" cy="62" r="38" className={styles.fbBody} />
                  <circle cx="47" cy="56" r="6" className={styles.fbEye} />
                  <circle cx="73" cy="56" r="6" className={styles.fbEye} />
                  <path d="M54 68h12l-6 8z" className={styles.fbEye} />
                </svg>
                <p>Birb could not load here: the Rive runtime or birb.riv is unavailable. The controls still respond, with nothing to animate.</p>
              </div>
            )}
            onReady={(a) => { api.current = a; setReady(true); setFailed(false); }}
            onError={() => { api.current = null; setReady(false); setFailed(true); }}
            onStateChange={onStateChange}
          />
        </div>
        <button
          type="button"
          className={styles.playButton}
          onClick={togglePlay}
          aria-label={paused ? 'Play animation' : 'Pause animation'}
        >
          {paused ? (
            <svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true"><path d="M6.5 4.5v11l9-5.5z" fill="currentColor" /></svg>
          ) : (
            <svg viewBox="0 0 20 20" width="18" height="18" aria-hidden="true"><path d="M6 4.5h2.6v11H6zM11.4 4.5H14v11h-2.6z" fill="currentColor" /></svg>
          )}
        </button>
      </div>

      <div className={styles.controls}>
        <button type="button" className={styles.button} data-kind="dance" aria-pressed={dance} onClick={toggleDance}>
          <span className={styles.eq} aria-hidden="true" data-on={(dance && !paused) || undefined}><i /><i /><i /></span>
          Dance
        </button>
        <button type="button" className={styles.button} data-kind="look" onClick={() => lookUp('button')}>
          <svg className={styles.lookIcon} viewBox="0 0 20 20" width="18" height="18" aria-hidden="true">
            <path d="M10 15.5v-11M5.5 9 10 4.5 14.5 9" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
          </svg>
          Look up
        </button>
      </div>

      <ul className={styles.cues} aria-label="State machine inputs">
        <li className={styles.cue}><span className={styles.cueKey}>dance</span><span ref={(el) => { cueRefs.current.dance = el; }} className={styles.cueValue}>{String(dance)}</span></li>
        <li className={styles.cue}><span className={styles.cueKey}>look up</span><span ref={(el) => { cueRefs.current.look = el; }} className={styles.cueValue}>trigger</span></li>
        <li className={styles.cue}><span className={styles.cueKey}>state</span><span className={styles.cueValue}>{failed ? '—' : state}</span></li>
      </ul>
      <p className={styles.hint}>{hint}</p>
      <p className={styles.srOnly} role="status">{said.text}{said.n % 2 ? ' ' : ''}</p>
    </section>
  );
}

'use client';
import { useCallback, useEffect, useRef } from 'react';
import { cssEase, duration as D } from '../../motion';

/**
 * The surface's signature move: when a DOM control drives a state machine input, a signal-coloured cue light sweeps
 * under that input's readout, in the same frame the canvas starts to react. Under reduced motion the readout only
 * flashes (opacity, ≤ 200 ms). Running sweeps are cancelled on unmount.
 */
export function useCueSweep(reduced: boolean): (el: Element | null) => void {
  const running = useRef(new Map<Element, Animation>());
  useEffect(() => {
    const map = running.current;
    return () => { for (const a of map.values()) a.cancel(); map.clear(); };
  }, []);
  return useCallback((el: Element | null) => {
    if (!el || typeof el.animate !== 'function') return;
    const map = running.current;
    map.get(el)?.cancel();
    const a = reduced
      ? el.animate([{ opacity: 0.4 }, { opacity: 1 }], { duration: D.fast, easing: 'linear' })
      // The cue element paints `background: linear-gradient(accent) no-repeat` at 0 size (see .cueValue): the light
      // grows in from the left, holds, and leaves to the right. The value text starts in the accent and eases back.
      : el.animate(
        [
          { backgroundSize: '0% 2px', backgroundPosition: '0% 100%', color: 'var(--mk-accent, #bf2f09)' },
          { backgroundSize: '100% 2px', backgroundPosition: '0% 100%', offset: 0.42 },
          { backgroundSize: '100% 2px', backgroundPosition: '100% 100%', offset: 0.58 },
          { backgroundSize: '0% 2px', backgroundPosition: '100% 100%' },
        ],
        { duration: D.slow + D.base, easing: cssEase('inOut') },
      );
    map.set(el, a);
    const done = () => { if (map.get(el) === a) map.delete(el); };
    a.finished.then(done, done);
  }, [reduced]);
}

'use client';
import { useEffect, useId, useRef, useState, type CSSProperties, type FocusEvent, type PointerEvent } from 'react';
import type { DeprecationId } from '@rive-app/canvas-lite';
import { cssEase, duration as D, useStudioMotion } from '../../motion';
import { useCueSweep } from './cue';
import { RiveCanvas, type RiveCanvasApi } from './RiveCanvas';
import styles from './styles.module.css';

const RATING = { src: '/rive/rating_animation.riv', artboard: 'New Artboard', stateMachine: 'State Machine 1' } as const;
/**
 * The 500 × 500 artboard is cropped to a band (fit "cover" on a 500 : 170 box, rows 165–335). Its stars sit at
 * x = 110 + 70·i, y = 245, so five equal slots from 15 % to 85 % of the width each hold one star: the native radios
 * are laid exactly over the drawn stars.
 */
const STARS = [1, 2, 3, 4, 5] as const;
const WORDS = ['Not rated yet', 'Not for me', 'It was fine', 'Good', 'Great', 'Loved it'] as const;
/** Reduced motion scrubs these animations (the states of the machine carry the same names). */
const animFor = (n: number) => (n <= 0 ? 'Idle_empty' : n === 1 ? '1_star' : `${n}_stars`);
/** A pre-data-binding sample: inputs, state names, and (for reduced motion) scrubbed animations. */
const QUIET: readonly DeprecationId[] = ['state-machine-inputs', 'state-change-events', 'animation-names', 'scrub'];
/** Sample data: an invented spread of earlier ratings (5★ … 1★). The visitor's own rating is added to it. */
const SAMPLE = [64, 38, 15, 7, 4] as const;
const STAR = 'M12 3.2c.4 0 .8.2 1 .6l2.2 4.6 5 .7c.9.1 1.3 1.2.6 1.9l-3.6 3.5.9 5c.2.9-.8 1.6-1.6 1.2L12 18.3l-4.5 2.4c-.8.4-1.8-.3-1.6-1.2l.9-5-3.6-3.5c-.7-.7-.3-1.8.6-1.9l5-.7 2.2-4.6c.2-.4.6-.6 1-.6z';

type Props = { index: string; tint: string };

export function RatingStars({ index, tint }: Props) {
  const { reduced } = useStudioMotion();
  const uid = useId();
  const api = useRef<RiveCanvasApi | null>(null);
  const ghostRef = useRef<HTMLCanvasElement>(null);
  const burstRef = useRef<HTMLSpanElement>(null);
  const cueRef = useRef<HTMLSpanElement>(null);
  const sweep = useCueSweep(reduced);

  const [ready, setReady] = useState(false);
  const [failed, setFailed] = useState(false);
  const [value, setValue] = useState(0);
  const [preview, setPreview] = useState<number | null>(null);
  const [state, setState] = useState('Idle_empty');
  const [said, setSaid] = useState({ text: '', n: 0 });
  const shown = preview ?? value;
  const previewing = preview !== null && preview !== value;

  // ── Canvas: full motion sets the number input and the state machine animates; reduced motion stops the machine
  // and scrubs the matching animation to its last frame, with a 160 ms cross-fade from a snapshot of the old frame.
  const mode = useRef<'machine' | 'frames'>('machine');
  const first = useRef(true);
  const fade = useRef<Animation | null>(null);
  const ringAnim = useRef<Animation | null>(null);
  useEffect(() => () => { fade.current?.cancel(); ringAnim.current?.cancel(); }, []);
  useEffect(() => {
    const a = api.current;
    if (!ready || !a) return;
    const { rive } = a;
    if (reduced) {
      const ghost = ghostRef.current;
      const src = a.canvas;
      if (!first.current && ghost && src.width && src.height && typeof ghost.animate === 'function') {
        ghost.width = src.width;
        ghost.height = src.height;
        const ctx = ghost.getContext('2d');
        if (ctx) {
          ctx.clearRect(0, 0, ghost.width, ghost.height);
          ctx.drawImage(src, 0, 0);
          fade.current?.cancel();
          fade.current = ghost.animate([{ opacity: 1 }, { opacity: 0 }], { duration: D.fast, easing: 'linear', fill: 'forwards' });
        }
      }
      const anim = animFor(shown);
      rive.stop();
      rive.pause(anim);
      rive.scrub(anim, 60); // one-shot animations clamp at their end: the settled frame
      mode.current = 'frames';
      setState(anim);
    } else {
      if (mode.current === 'frames') { rive.stop(); rive.play(RATING.stateMachine); mode.current = 'machine'; }
      const input = a.input('rating');
      if (input) input.value = shown;
    }
    first.current = false;
  }, [shown, reduced, ready]);

  const say = (text: string) => setSaid((s) => ({ text, n: s.n + 1 }));
  const committed = useRef(0);
  const commit = (n: number) => {
    if (n === committed.current) return;
    committed.current = n;
    setValue(n);
    say(`Rated ${n} out of 5: ${WORDS[n]}.`);
    sweep(cueRef.current);
    // Reward the person's own choice once: a ring leaves the chosen star (decorative, full motion only).
    const ring = burstRef.current;
    if (!reduced && ring && typeof ring.animate === 'function') {
      ring.style.setProperty('--at', String(n));
      ringAnim.current?.cancel();
      ringAnim.current = ring.animate(
        [
          { transform: 'translate(-50%, -50%) scale(0.6)', opacity: 1, borderWidth: '3px' },
          { transform: 'translate(-50%, -50%) scale(1.3)', opacity: 0.75, borderWidth: '2px', offset: 0.4 },
          { transform: 'translate(-50%, -50%) scale(1.8)', opacity: 0, borderWidth: '1px' },
        ],
        { duration: D.slow + D.base, easing: cssEase('standard') },
      );
    }
  };
  const clear = () => {
    if (!committed.current) return;
    committed.current = 0;
    setValue(0);
    setPreview(null);
    say('Rating cleared.');
    sweep(cueRef.current);
  };

  // ── Pointer: hover previews (mouse, pen); a touch drag across the stars previews and commits on release.
  const drag = useRef<number | null>(null);
  const slotAt = (x: number, row: HTMLElement) => {
    const r = row.getBoundingClientRect();
    return Math.min(5, Math.max(1, Math.floor(((x - r.left) / r.width) * 5) + 1));
  };
  const onMove = (e: PointerEvent<HTMLDivElement>) => {
    if (e.pointerType === 'touch' && drag.current !== e.pointerId) return;
    setPreview(slotAt(e.clientX, e.currentTarget));
  };
  const onDown = (e: PointerEvent<HTMLDivElement>) => {
    if (e.pointerType !== 'touch') return;
    drag.current = e.pointerId;
    setPreview(slotAt(e.clientX, e.currentTarget));
  };
  const onUp = (e: PointerEvent<HTMLDivElement>) => {
    if (drag.current !== e.pointerId) return;
    drag.current = null;
    commit(slotAt(e.clientX, e.currentTarget));
    setPreview(null);
  };
  const onLeave = (e: PointerEvent<HTMLDivElement>) => {
    if (drag.current === e.pointerId) drag.current = null;
    setPreview(null);
  };
  const onBlur = (e: FocusEvent<HTMLFieldSetElement>) => {
    if (!e.currentTarget.contains(e.relatedTarget as Node | null)) setPreview(null);
  };

  return (
    <section className={styles.panel} aria-labelledby={`${uid}t`} style={{ '--i': 1 } as CSSProperties}>
      <header className={styles.head}>
        <span className={styles.index} aria-hidden="true">{index}</span>
        <h3 id={`${uid}t`} className={styles.title}>Rating</h3>
        <span className={styles.status} data-live={(ready && !!value) || undefined}>
          <span className={styles.dot} aria-hidden="true" />
          {value ? `${value} of 5` : 'not rated'}
        </span>
      </header>

      <div className={styles.rateBody}>
        <fieldset className={styles.fieldset} onBlur={onBlur}>
          <legend className={styles.prompt}>How was the performance?</legend>
          <div className={styles.band} data-tint={tint} data-ready={ready || undefined} data-failed={failed || undefined}>
            {/* Drawn DOM stars: the static picture while the runtime loads, and the fallback if it never does. */}
            <div className={styles.bandArt} aria-hidden="true">
              {STARS.map((i) => (
                <svg key={i} className={styles.bandStar} viewBox="0 0 24 24" data-on={i <= shown || undefined} style={{ '--at': i } as CSSProperties}>
                  <path d={STAR} />
                </svg>
              ))}
            </div>
            <RiveCanvas
              className={styles.bandCanvas}
              src={RATING.src}
              artboard={RATING.artboard}
              stateMachine={RATING.stateMachine}
              fit="cover"
              paused={reduced}
              quietDeprecations={QUIET}
              onReady={(a) => { api.current = a; first.current = true; mode.current = 'machine'; setReady(true); setFailed(false); }}
              onError={() => { api.current = null; setReady(false); setFailed(true); }}
              onStateChange={(states) => { if (!reduced && states.length) setState(states[states.length - 1]); }}
            />
            <canvas ref={ghostRef} className={styles.ghost} data-ghost="" aria-hidden="true" />
            <span ref={burstRef} className={styles.burst} aria-hidden="true" />
            <div
              className={styles.slots}
              onPointerMove={onMove}
              onPointerDown={onDown}
              onPointerUp={onUp}
              onPointerCancel={onLeave}
              onPointerLeave={onLeave}
            >
              {STARS.map((i) => (
                <label key={i} className={styles.slot}>
                  <input
                    className={styles.radio}
                    type="radio"
                    name={`${uid}rating`}
                    value={i}
                    checked={value === i}
                    onChange={() => commit(i)}
                    onFocus={() => setPreview(i)}
                  />
                  <span className={styles.ring} aria-hidden="true" />
                  <span className={styles.srOnly}>{i === 1 ? '1 star' : `${i} stars`}</span>
                </label>
              ))}
            </div>
          </div>
        </fieldset>

        <div className={styles.result}>
          <p className={styles.score} data-preview={previewing || undefined} data-empty={!shown || undefined}>
            <span key={shown} className={styles.scoreNum}>{shown || '–'}</span>
            <span className={styles.scoreOf}>/ 5</span>
          </p>
          <p className={styles.word}>
            {previewing ? <><span className={styles.tag}>Preview</span>{WORDS[shown]}</> : WORDS[value]}
          </p>
          <button type="button" className={styles.textButton} onClick={clear} aria-disabled={!value || undefined}>Clear</button>
        </div>

        <Breakdown value={value} />
      </div>

      <ul className={styles.cues} aria-label="State machine inputs">
        <li className={styles.cue}><span className={styles.cueKey}>rating</span><span ref={cueRef} className={styles.cueValue}>{shown}</span></li>
        <li className={styles.cue}><span className={styles.cueKey}>{reduced ? 'frame' : 'state'}</span><span className={styles.cueValue}>{failed ? '—' : state}</span></li>
      </ul>
      <p className={styles.hint}>
        {failed
          ? 'The animation could not load, so the stars are drawn by the page. The radio buttons work the same.'
          : 'Hover or focus a star to preview it; click, tap, drag or use the arrow keys to rate.'}
      </p>
      <p className={styles.srOnly} role="status">{said.text}{said.n % 2 ? ' ' : ''}</p>
    </section>
  );
}

/** Sample ratings with the visitor's vote added: bars spring to their new length, the average follows. */
function Breakdown({ value }: { value: number }) {
  const uid = useId();
  const counts = SAMPLE.map((c, i) => c + (value === 5 - i ? 1 : 0));
  const total = counts.reduce((a, b) => a + b, 0);
  const mean = counts.reduce((a, c, i) => a + c * (5 - i), 0) / total;
  const max = Math.max(...counts);
  return (
    <div className={styles.breakdown} aria-labelledby={`${uid}h`} role="group">
      <p className={styles.breakdownHead}>
        <span id={`${uid}h`}>Sample ratings{value ? ', yours included' : ''}</span>
        <span className={styles.breakdownMean}><strong>{mean.toFixed(2)}</strong> avg · {total}</span>
      </p>
      <ul className={styles.bars}>
        {counts.map((c, i) => {
          const stars = 5 - i;
          return (
            <li key={stars} className={styles.bar} data-mine={value === stars || undefined}>
              <span className={styles.barKey} aria-hidden="true">{stars}</span>
              <span className={styles.srOnly}>{stars === 1 ? '1 star' : `${stars} stars`}: </span>
              <span className={styles.barTrack} aria-hidden="true">
                <span className={styles.barFill} style={{ transform: `scaleX(${(c / max).toFixed(4)})` }} />
              </span>
              <span className={styles.barCount}>{c}</span>
            </li>
          );
        })}
      </ul>
    </div>
  );
}

/* RiveCanvas: the element is sized by its parent (or className/style); the canvas fills it. */
.root {
  position: relative;
  display: block;
  box-sizing: border-box;
  min-width: 0;
  min-height: 0;
}
.surface {
  display: block;
  width: 100%;
  height: 100%;
  opacity: 0;
  transition: opacity var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, cubic-bezier(0.2, 0, 0, 1));
}
.root[data-status='ready'] .surface { opacity: 1; }
.root[data-status='error'] .surface { visibility: hidden; }
.layer {
  position: absolute;
  inset: 0;
  display: grid;
  place-items: center;
}
/* Reduced motion: the canvas appearing is a state change, so it may fade, briefly. */
.root[data-reduced] .surface { transition-duration: var(--mk-duration-fast, 160ms); }
@media (prefers-reduced-motion: reduce) {
  .surface { transition-duration: var(--mk-duration-fast, 160ms); }
}

'use client';
/**
 * RiveCanvas — a content-agnostic React wrapper around the @rive-app/canvas-lite runtime.
 *
 * - The runtime is a dynamic import inside an effect: pages that never mount a RiveCanvas never download it.
 * - The WASM comes from your origin (`wasmUrl`, `wasmFallbackUrl`): no request goes to a CDN, and Rive's own asset
 *   CDN is off. The binary and the .riv bytes are fetched here first, so a missing file shows `fallback` instead of
 *   Rive logging an error.
 * - The drawing buffer follows the element (ResizeObserver, device pixel ratio capped by `maxPixelRatio`).
 * - Rendering stops offscreen and in hidden tabs; `paused` stops advancing but keeps the frame.
 * - Without a `paused` prop, playback follows reduced motion: a still first frame, no autoplay.
 * - The canvas is aria-hidden: give the element a `label`, and put the meaning in DOM controls.
 *
 * Driving it: `onReady` hands over the Rive instance and `input(name)` for state machine inputs. Files authored with
 * data binding expose view model properties through `api.rive.viewModelInstance` instead.
 */
import { useCallback, useEffect, useRef, useState, type CSSProperties, type ReactNode } from 'react';
import type { DeprecationId, Rive, StateMachineInput } from '@rive-app/canvas-lite';
import { useStudioMotion } from '../../motion';
import styles from './rive-canvas.module.css';

export type RiveRuntime = typeof import('@rive-app/canvas-lite');
export type RiveFit = 'contain' | 'cover' | 'fill' | 'fitWidth' | 'fitHeight' | 'scaleDown' | 'none' | 'layout';
export type RiveAlignment =
  | 'center' | 'topLeft' | 'topCenter' | 'topRight' | 'centerLeft' | 'centerRight' | 'bottomLeft' | 'bottomCenter' | 'bottomRight';

export interface RiveCanvasApi {
  /** The live instance: play(), pause(), reset(), data binding, events. */
  rive: Rive;
  /** The runtime module, for its enums and classes (Layout, Fit, EventType…). */
  runtime: RiveRuntime;
  /** The canvas Rive draws into (aria-hidden). */
  canvas: HTMLCanvasElement;
  /** An input of the state machine by name. Looked up on every call, so it stays valid after stop() or reset(). */
  input: (name: string) => StateMachineInput | undefined;
}

export interface RiveCanvasProps {
  /** URL of the .riv file. */
  src: string;
  artboard?: string;
  stateMachine?: string;
  fit?: RiveFit;
  alignment?: RiveAlignment;
  /** Stop advancing (the frame stays). Leave undefined to follow reduced motion: still under reduce, playing otherwise. */
  paused?: boolean;
  /** Where the runtime's WASM is served from. Defaults to the gallery's copy on the same origin. */
  wasmUrl?: string;
  /** Second WASM build for older engines, tried when the first fails to compile. `null` turns the retry off. */
  wasmFallbackUrl?: string | null;
  /** Upper bound for the device pixel ratio of the drawing buffer. */
  maxPixelRatio?: number;
  /** Accessible name of the picture (the element gets role="img"). Omit for a decorative canvas. */
  label?: string;
  /** Shown instead of the canvas when the runtime or the file cannot load. */
  fallback?: ReactNode;
  /** Shown while loading. */
  loading?: ReactNode;
  /**
   * Let listeners authored inside the file react to the pointer on the canvas. Off by default: a keyboard cannot
   * reach them, so drive inputs from DOM controls instead.
   */
  pointerListeners?: boolean;
  /** Deprecation ids to silence, merged into the page-wide `Rive.suppressDeprecationWarnings`. */
  quietDeprecations?: readonly DeprecationId[];
  onReady?: (api: RiveCanvasApi) => void;
  onError?: (error: Error) => void;
  /** Names of the states the state machine entered. Subscribed only when given at mount. */
  onStateChange?: (states: string[]) => void;
  className?: string;
  style?: CSSProperties;
}

const DEFAULT_WASM = '/rive/rive.wasm';
const DEFAULT_WASM_FALLBACK = '/rive/rive_fallback.wasm';

const toError = (e: unknown): Error => (e instanceof Error ? e : new Error(typeof e === 'string' ? e : 'Rive failed to load'));

async function fetchBytes(url: string): Promise<ArrayBuffer> {
  const res = await fetch(url);
  if (!res.ok) throw new Error(`${url} answered HTTP ${res.status}`);
  return res.arrayBuffer();
}

/* One runtime per page (Rive's loader is a singleton): the first mount's URLs win. A failed load is forgotten so the
   next mount retries. */
let runtimeLoad: Promise<RiveRuntime> | null = null;
function loadRuntime(wasmUrl: string, fallbackUrl: string | null): Promise<RiveRuntime> {
  if (runtimeLoad) return runtimeLoad;
  const load = (async () => {
    if (typeof WebAssembly !== 'object' || typeof fetch !== 'function') throw new Error('This browser cannot run WebAssembly');
    const [mod, wasm] = await Promise.all([import('@rive-app/canvas-lite'), fetchBytes(wasmUrl)]);
    // Bundlers expose the UMD build's exports by name; Node's CommonJS interop only as `default`.
    const ns = mod as RiveRuntime & { default?: RiveRuntime };
    const rt = typeof ns.RuntimeLoader === 'function' ? ns : ns.default;
    if (!rt || typeof rt.RuntimeLoader !== 'function') throw new Error('Unexpected @rive-app/canvas-lite module shape');
    rt.RuntimeLoader.setWasmUrl(wasmUrl);
    rt.RuntimeLoader.setWasmFallbackUrl(fallbackUrl);
    rt.RuntimeLoader.setWasmBinary(wasm);
    await rt.RuntimeLoader.awaitInstance();
    rt.RuntimeLoader.setWasmBinary(null); // compiled: let the bytes go
    return rt;
  })();
  runtimeLoad = load;
  load.catch(() => { if (runtimeLoad === load) runtimeLoad = null; });
  return load;
}

/* .riv bytes by URL, shared by every instance (StrictMode remounts and Replay reuse them). Rive copies them into
   WASM memory, so one buffer can feed many instances. */
const files = new Map<string, Promise<ArrayBuffer>>();
function loadFile(url: string): Promise<ArrayBuffer> {
  let p = files.get(url);
  if (!p) {
    p = fetchBytes(url);
    files.set(url, p);
    p.catch(() => { if (files.get(url) === p) files.delete(url); });
    if (files.size > 8) files.delete(files.keys().next().value as string);
  }
  return p;
}

type Status = 'loading' | 'ready' | 'error';

export function RiveCanvas({
  src, artboard, stateMachine, fit = 'contain', alignment = 'center', paused, wasmUrl = DEFAULT_WASM,
  wasmFallbackUrl = DEFAULT_WASM_FALLBACK, maxPixelRatio = 2, label, fallback, loading, pointerListeners = false,
  quietDeprecations, onReady, onError, onStateChange, className, style,
}: RiveCanvasProps) {
  const { reduced } = useStudioMotion();
  const wantPaused = paused ?? reduced;
  const rootRef = useRef<HTMLDivElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const [status, setStatus] = useState<Status>('loading');

  // Mutable bridge between the instance and React: nothing here triggers a render.
  const ctl = useRef({ rive: null as Rive | null, runtime: null as RiveRuntime | null, appliedPaused: true, inView: true, open: false, w: 0, h: 0 });
  const live = useRef({ wantPaused, onReady, onError, onStateChange, fit, alignment, maxPixelRatio });
  live.current = { wantPaused, onReady, onError, onStateChange, fit, alignment, maxPixelRatio };

  const isOpen = () => ctl.current.inView && !(typeof document !== 'undefined' && document.hidden);

  /** Match the drawing buffer to the element's layout size (transforms do not count) at a capped pixel ratio. */
  const resize = useCallback(() => {
    const c = ctl.current;
    const r = c.rive;
    const canvas = canvasRef.current;
    if (!r || !canvas || c.w <= 0 || c.h <= 0) return;
    const dpr = Math.min(window.devicePixelRatio || 1, live.current.maxPixelRatio);
    const w = Math.max(1, Math.round(c.w * dpr));
    const h = Math.max(1, Math.round(c.h * dpr));
    if (canvas.width === w && canvas.height === h && r.devicePixelRatioUsed === dpr) return;
    canvas.width = w;
    canvas.height = h;
    r.devicePixelRatioUsed = dpr;
    r.resizeToCanvas();
    if (live.current.fit === 'layout') { r.artboardWidth = c.w; r.artboardHeight = c.h; }
    // drawFrame() restarts a playing loop, so only draw while rendering is allowed; startRendering() redraws later.
    if (c.open) r.drawFrame();
  }, []);

  /** Apply playback (paused prop) first, then the offscreen/hidden gate: play() restarts rendering on its own. */
  const sync = useCallback(() => {
    const c = ctl.current;
    const r = c.rive;
    if (!r) return;
    const want = live.current.wantPaused;
    if (c.appliedPaused !== want) {
      c.appliedPaused = want;
      if (want) r.pause();
      else r.play();
    }
    c.open = isOpen();
    if (c.open) r.startRendering();
    else r.stopRendering();
  }, []);

  const stateListener = !!onStateChange;
  const quietKey = quietDeprecations?.join(',') ?? '';

  // Create the instance; recreate it when the source changes.
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    let cancelled = false;
    let instance: Rive | null = null;
    setStatus('loading');
    const fail = (e: unknown) => {
      if (cancelled) return;
      ctl.current.rive = null;
      setStatus('error');
      live.current.onError?.(toError(e));
    };
    (async () => {
      try {
        const [rt, buffer] = await Promise.all([loadRuntime(wasmUrl, wasmFallbackUrl), loadFile(src)]);
        if (cancelled) return;
        if (quietKey) {
          const ids = new Set([...rt.Rive.suppressDeprecationWarnings, ...(quietKey.split(',') as DeprecationId[])]);
          rt.Rive.suppressDeprecationWarnings = [...ids];
        }
        const startPaused = live.current.wantPaused;
        const fitValue = Object.values(rt.Fit).find((v) => v === live.current.fit) ?? rt.Fit.Contain;
        const alignValue = Object.values(rt.Alignment).find((v) => v === live.current.alignment) ?? rt.Alignment.Center;
        const r: Rive = new rt.Rive({
          canvas,
          buffer,
          artboard,
          stateMachine,
          autoplay: !startPaused,
          layout: new rt.Layout({ fit: fitValue, alignment: alignValue }),
          enableSettling: true,
          enableRiveAssetCDN: false,
          shouldDisableRiveListeners: !pointerListeners,
          shouldDisableGamepad: true,
          isTouchScrollEnabled: true,
          onLoad: () => {
            if (cancelled) return;
            const c = ctl.current;
            c.rive = r;
            c.runtime = rt;
            c.appliedPaused = startPaused;
            c.open = true;
            resize();
            setStatus('ready');
            live.current.onReady?.({
              rive: r,
              runtime: rt,
              canvas,
              input: (name) => (stateMachine ? r.stateMachineInputs(stateMachine)?.find((i) => i.name === name) : undefined),
            });
            // Rive draws (and may schedule frames) right after onLoad returns: gate rendering once it has.
            queueMicrotask(() => { if (!cancelled) sync(); });
          },
          onLoadError: (e) => fail(e.data),
          onStateChange: stateListener
            ? (e) => { if (!cancelled && Array.isArray(e.data)) live.current.onStateChange?.(e.data.map(String)); }
            : undefined,
        });
        instance = r;
      } catch (e) {
        fail(e);
      }
    })();
    return () => {
      cancelled = true;
      if (ctl.current.rive === instance) { ctl.current.rive = null; ctl.current.runtime = null; }
      instance?.cleanup();
    };
  }, [src, artboard, stateMachine, wasmUrl, wasmFallbackUrl, pointerListeners, stateListener, quietKey, resize, sync]);

  // Playback follows `paused` (or reduced motion when uncontrolled).
  useEffect(() => { sync(); }, [wantPaused, sync]);

  // Fit and alignment can change without reloading.
  useEffect(() => {
    const { rive: r, runtime: rt } = ctl.current;
    if (!r || !rt) return;
    const fitValue = Object.values(rt.Fit).find((v) => v === fit) ?? rt.Fit.Contain;
    const alignValue = Object.values(rt.Alignment).find((v) => v === alignment) ?? rt.Alignment.Center;
    if (r.layout.fit === fitValue && r.layout.alignment === alignValue) return;
    r.layout = new rt.Layout({ fit: fitValue, alignment: alignValue });
    r.resizeToCanvas();
    if (ctl.current.open) r.drawFrame();
  }, [fit, alignment, status]);

  // Drawing buffer size: element size from a ResizeObserver, device pixel ratio from a resolution media query.
  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas || typeof ResizeObserver === 'undefined') return;
    const ro = new ResizeObserver(([entry]) => {
      ctl.current.w = entry.contentRect.width;
      ctl.current.h = entry.contentRect.height;
      resize();
    });
    ro.observe(canvas);
    let mql: MediaQueryList | null = null;
    const onDpr = () => { watch(); resize(); };
    const watch = () => {
      mql?.removeEventListener('change', onDpr);
      mql = typeof window.matchMedia === 'function' ? window.matchMedia(`(resolution: ${window.devicePixelRatio || 1}dppx)`) : null;
      mql?.addEventListener('change', onDpr);
    };
    watch();
    return () => { ro.disconnect(); mql?.removeEventListener('change', onDpr); };
  }, [resize]);
  useEffect(() => { resize(); }, [maxPixelRatio, resize]);

  // No frames while offscreen or in a hidden tab.
  useEffect(() => {
    const root = rootRef.current;
    if (!root) return;
    const io = typeof IntersectionObserver !== 'undefined'
      ? new IntersectionObserver(([e]) => { ctl.current.inView = e.isIntersecting; sync(); })
      : null;
    io?.observe(root);
    document.addEventListener('visibilitychange', sync);
    return () => { io?.disconnect(); document.removeEventListener('visibilitychange', sync); };
  }, [sync]);

  const failed = status === 'error';
  return (
    <div
      ref={rootRef}
      className={className ? `${styles.root} ${className}` : styles.root}
      style={style}
      data-status={status}
      data-reduced={reduced || undefined}
      role={label && !failed ? 'img' : undefined}
      aria-label={label && !failed ? label : undefined}
    >
      <canvas ref={canvasRef} className={styles.surface} aria-hidden="true" />
      {status === 'loading' && loading ? <div className={styles.layer}>{loading}</div> : null}
      {failed && fallback ? <div className={styles.layer}>{fallback}</div> : null}
    </div>
  );
}

/* Rive State Machine — a small stage and a scorecard, set like a cue sheet: mono indices and input read-outs,
   hairline rules, ink controls. Light comes from above: panels carry a top highlight, a tight contact shadow and a
   wide soft one; the stage has a spotlight on its back wall and a light pool on the floor. */

.root {
  container-type: inline-size;
  box-sizing: border-box;
  align-self: stretch;
  justify-self: stretch;
  width: 100%;
  padding: clamp(0.75rem, 3.5cqi, 2rem);
  color: var(--mk-ink, #11110f);
  font-family: var(--mk-font-text, ui-sans-serif, system-ui, sans-serif);
}
.grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: clamp(0.875rem, 2.4cqi, 1.25rem);
  width: 100%;
  max-width: 62rem;
  margin-inline: auto;
}
.grid[data-scene='character'] { max-width: 34rem; }
.grid[data-scene='rating'] { max-width: 30rem; }
@container (min-width: 680px) {
  .grid[data-scene='both'] { grid-template-columns: minmax(0, 1.12fr) minmax(0, 1fr); }
}

/* ── Panels ───────────────────────────────────────────────────────────── */
.panel {
  container-type: inline-size;
  position: relative;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  grid-auto-rows: auto;
  gap: 0.75rem;
  min-width: 0;
  padding: 0.75rem;
  border: 1px solid var(--mk-line, #11110f24);
  border-radius: var(--mk-radius-l, 18px);
  background: var(--mk-surface, #fbf9f4);
  box-shadow: 0 1px 2px rgb(17 17 15 / 0.07), 0 22px 44px -30px rgb(17 17 15 / 0.42);
  box-shadow:
    inset 0 1px 0 light-dark(rgb(255 255 255 / 0.9), rgb(255 255 255 / 0.05)),
    0 1px 2px rgb(17 17 15 / 0.07),
    0 22px 44px -30px rgb(17 17 15 / 0.42);
}
.head {
  display: flex;
  align-items: center;
  gap: 0.625rem;
  min-width: 0;
  padding: 0.125rem 0.25rem 0;
}
.index, .status, .cues, .credit, .loadingNote {
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  font-variant-numeric: tabular-nums;
}
.index { color: var(--mk-ink-muted, #5c5a52); }
.title {
  margin: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: 1.0625rem;
  font-weight: 650;
  line-height: 1;
  letter-spacing: -0.02em;
}
.status {
  display: inline-flex;
  align-items: center;
  gap: 0.45rem;
  margin-left: auto;
  text-transform: uppercase;
  white-space: nowrap;
  color: var(--mk-ink-muted, #5c5a52);
}
.dot {
  width: 0.4375rem;
  height: 0.4375rem;
  border-radius: 50%;
  background: currentColor;
  opacity: 0.45;
  transition: background-color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease), box-shadow var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
}
.status[data-live] { color: var(--mk-ink, #11110f); }
.status[data-live] .dot {
  opacity: 1;
  background: var(--mk-accent, #bf2f09);
  box-shadow: 0 0 0 3px color-mix(in oklab, var(--mk-accent, #bf2f09) 20%, transparent);
}

/* ── Stage ────────────────────────────────────────────────────────────── */
.stage {
  --wall: color-mix(in oklab, var(--mk-ink, #11110f) 3.5%, var(--mk-surface, #fbf9f4));
  --floor: color-mix(in oklab, var(--mk-ink, #11110f) 9%, var(--mk-surface, #fbf9f4));
  --glow: rgb(255 255 255 / 0.9);
  --glow: light-dark(rgb(255 255 255 / 0.92), rgb(176 222 255 / 0.12));
  --rule: color-mix(in oklab, var(--mk-ink, #11110f) 9%, transparent);
  position: relative;
  isolation: isolate;
  overflow: hidden;
  min-height: clamp(16rem, 74cqi, 25rem);
  border-radius: calc(var(--mk-radius-l, 18px) - 0.375rem);
  /* A cyclorama: the wall curves into the floor without a seam; the corners fall off into a soft vignette. */
  background:
    radial-gradient(135% 105% at 50% 36%, transparent 58%, color-mix(in oklab, var(--mk-ink, #11110f) 7%, transparent) 100%),
    linear-gradient(to bottom, var(--wall) 0%, var(--wall) 54%, var(--floor) 82%, color-mix(in oklab, var(--floor) 93%, var(--mk-ink, #11110f)) 100%);
  box-shadow: inset 0 0 0 1px var(--mk-line, #11110f24);
}
.wall {
  position: absolute;
  inset: -14% -14% 18%;
  z-index: -2;
  background: radial-gradient(40% 56% at 50% 50%, var(--glow), transparent 72%);
  transition: transform var(--mk-duration-cinematic, 900ms) var(--mk-ease-enter, cubic-bezier(0.05, 0.7, 0.1, 1));
}
.stage[data-reactive] .wall { will-change: transform; }
/* The light pool Birb stands in; its own contact shadow is part of the artwork. */
.floor {
  position: absolute;
  inset: 60% 0 0;
  z-index: -1;
  background: radial-gradient(36% 44% at 50% 72%, var(--glow), transparent 76%);
}
.stage[data-backdrop='grid'] .wall {
  background:
    radial-gradient(40% 56% at 50% 50%, var(--glow), transparent 72%),
    linear-gradient(var(--rule) 1px, transparent 1px) 50% 0 / 100% 1.75rem,
    linear-gradient(90deg, var(--rule) 1px, transparent 1px) 50% 0 / 1.75rem 100%;
}
.stage[data-backdrop='grid'] { background: var(--wall); }
.stage[data-backdrop='grid'] .floor {
  inset: 70% 0 0;
  overflow: hidden;
  background: radial-gradient(36% 60% at 50% 62%, var(--glow), transparent 76%), var(--floor);
  box-shadow: 0 -1px 0 var(--rule);
}
.stage[data-backdrop='grid'] .floor::before {
  content: '';
  position: absolute;
  inset: 0 -80% -60%;
  background:
    linear-gradient(var(--rule) 1px, transparent 1px) 0 0 / 100% 1.5rem,
    linear-gradient(90deg, var(--rule) 1px, transparent 1px) 50% 0 / 2.25rem 100%;
  transform: perspective(14rem) rotateX(62deg);
  transform-origin: 50% 0;
  -webkit-mask-image: linear-gradient(to bottom, transparent, #000 45%);
  mask-image: linear-gradient(to bottom, transparent, #000 45%);
}
/* No backdrop: the artwork is transparent, so Birb and its own shadow stand on the panel. */
.stage[data-backdrop='none'] { background: transparent; box-shadow: inset 0 0 0 1px var(--mk-line, #11110f24); }
.stage[data-backdrop='none'] .wall, .stage[data-backdrop='none'] .floor { display: none; }

.birdBox {
  position: absolute;
  left: 50%;
  bottom: 3%;
  height: 92%;
  aspect-ratio: 1;
  max-width: 100%;
  translate: -50% 0;
}
.fill { width: 100%; height: 100%; }
.loadingNote { color: var(--mk-ink-muted, #5c5a52); align-self: end; margin-bottom: 18%; }
.birdFallback {
  display: grid;
  justify-items: center;
  gap: 0.5rem;
  max-width: 17rem;
  padding: 1rem;
  text-align: center;
  font-size: 0.8125rem;
  line-height: 1.45;
  color: var(--mk-ink-muted, #5c5a52);
}
.birdFallback p { margin: 0; }
.fbShadow { fill: var(--mk-ink, #11110f); opacity: 0.08; }
.fbBody { fill: none; stroke: var(--mk-ink-muted, #5c5a52); stroke-width: 2; stroke-dasharray: 5 5; }
.fbEye { fill: var(--mk-ink-muted, #5c5a52); }

.playButton {
  position: absolute;
  top: 0.625rem;
  right: 0.625rem;
  z-index: 2;
  display: grid;
  place-items: center;
  width: 2.75rem;
  height: 2.75rem;
  padding: 0;
  border: 1px solid color-mix(in oklab, var(--mk-ink, #11110f) 20%, transparent);
  border-radius: 50%;
  background: color-mix(in oklab, var(--mk-surface, #fbf9f4) 88%, transparent);
  color: var(--mk-ink, #11110f);
  cursor: pointer;
  box-shadow: 0 1px 1px rgb(17 17 15 / 0.08), 0 6px 14px -8px rgb(17 17 15 / 0.35);
  transition:
    transform var(--rs-spring-ms, 360ms) var(--rs-spring, var(--mk-ease-emphasized, ease)),
    background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.playButton:hover { background: var(--mk-surface, #fbf9f4); }
.playButton:active { transform: scale(0.92); transition-duration: var(--mk-duration-instant, 90ms); }
.playButton:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }

/* ── Controls ─────────────────────────────────────────────────────────── */
.controls { display: flex; flex-wrap: wrap; gap: 0.5rem; }
.button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 0.55rem;
  min-height: 2.75rem;
  padding: 0 1.125rem 0 0.9rem;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: 999px;
  background: var(--mk-surface, #fbf9f4);
  color: var(--mk-ink, #11110f);
  font: inherit;
  font-size: 0.9375rem;
  font-weight: 600;
  letter-spacing: -0.005em;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
  /* Lifted: tight contact shadow + wide soft one. Pressed: the soft one collapses into the contact one. */
  box-shadow: 0 1px 0 rgb(17 17 15 / 0.1), 0 8px 16px -12px rgb(17 17 15 / 0.55);
  transition:
    transform var(--rs-spring-ms, 360ms) var(--rs-spring, var(--mk-ease-emphasized, ease)),
    box-shadow var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease),
    background-color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease),
    color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
}
.button:hover { box-shadow: 0 1px 0 rgb(17 17 15 / 0.1), 0 12px 22px -12px rgb(17 17 15 / 0.6); }
.button:active {
  transform: scale(0.96);
  box-shadow: 0 0 0 rgb(17 17 15 / 0.1), 0 2px 4px -2px rgb(17 17 15 / 0.45);
  transition-duration: var(--mk-duration-instant, 90ms);
}
.button:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 3px; }
.button[aria-pressed='true'] {
  border-color: var(--mk-ink, #11110f);
  background: var(--mk-ink, #11110f);
  color: var(--mk-surface, #fbf9f4);
}
.lookIcon { transition: transform var(--rs-spring-ms, 360ms) var(--rs-spring, var(--mk-ease-emphasized, ease)); }
.button[data-kind='look']:active .lookIcon { transform: translateY(-3px); transition-duration: var(--mk-duration-instant, 90ms); }

/* Equaliser: three bars, still until Birb dances. */
.eq { display: inline-flex; align-items: flex-end; gap: 2px; width: 14px; height: 14px; }
.eq i { width: 3px; height: 100%; border-radius: 1px; background: currentColor; transform: scaleY(0.4); transform-origin: 50% 100%; }
.eq i:nth-child(2) { transform: scaleY(0.75); }
.eq i:nth-child(3) { transform: scaleY(0.55); }

/* ── Input read-outs (the cue list) ───────────────────────────────────── */
.cues {
  display: flex;
  flex-wrap: wrap;
  gap: 0.375rem 1.125rem;
  margin: 0;
  padding: 0.6rem 0.25rem 0;
  list-style: none;
  border-top: 1px solid var(--mk-line, #11110f24);
}
.cue { display: inline-flex; align-items: baseline; gap: 0.5rem; min-width: 0; }
.cueKey { color: var(--mk-ink-muted, #5c5a52); }
.cueValue {
  padding-bottom: 3px;
  font-weight: 600;
  color: var(--mk-ink, #11110f);
  background: linear-gradient(var(--mk-accent, #bf2f09), var(--mk-accent, #bf2f09)) no-repeat 0% 100% / 0% 2px;
}
.hint {
  margin: 0;
  padding: 0 0.25rem 0.125rem;
  font-size: 0.8125rem;
  line-height: 1.45;
  color: var(--mk-ink-muted, #5c5a52);
  text-wrap: pretty;
}

/* ── Rating ───────────────────────────────────────────────────────────── */
.rateBody { display: grid; align-content: center; gap: 1rem; min-width: 0; padding: 0.75rem 0.25rem 0.25rem; }
.fieldset { min-width: 0; margin: 0; padding: 0; border: 0; }
.prompt {
  display: block;
  margin: 0 0 0.875rem;
  padding: 0;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-size: clamp(1.375rem, 7.5cqi, 1.875rem);
  font-weight: 700;
  line-height: 1.02;
  letter-spacing: -0.03em;
  text-wrap: balance;
}
.band {
  --band-hue: #ff0a6a;
  position: relative;
  isolation: isolate;
  overflow: hidden;
  aspect-ratio: 500 / 170;
  border-radius: var(--mk-radius-m, 10px);
  box-shadow: 0 1px 1px rgb(17 17 15 / 0.1), 0 16px 30px -20px color-mix(in oklab, var(--band-hue) 75%, transparent);
}
.band::after { /* a hairline inner edge and a highlight along the top, from the same overhead light */
  content: '';
  position: absolute;
  inset: 0;
  z-index: 3;
  border-radius: inherit;
  box-shadow: inset 0 0 0 1px rgb(0 0 0 / 0.08), inset 0 1px 0 rgb(255 255 255 / 0.28);
  pointer-events: none;
}
/* The artboard's own gradient (sampled), cropped like the canvas: a square as wide as the band, centred. */
.bandArt {
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, #ff2fd3, #ff003f) 50% 50% / 100% 294.12%;
  transition: opacity var(--mk-duration-moderate, 360ms) var(--mk-ease-standard, ease);
}
.band[data-ready] .bandArt { opacity: 0; }
.bandStar {
  position: absolute;
  top: 47.06%;
  left: calc(15% + (var(--at, 1) - 0.5) * 14%);
  width: 10.4%;
  translate: -50% -50%;
  fill: #6e0228;
  stroke: #c3157e;
  stroke-width: 1.4;
  stroke-linejoin: round;
}
.bandStar[data-on] { fill: #fff8fb; }
.bandCanvas, .ghost { position: absolute; inset: 0; width: 100%; height: 100%; }
.ghost { opacity: 0; pointer-events: none; }
.band[data-failed] .bandCanvas { display: none; }
/* Accent treatment: keep the artwork's lights and darks (luminosity blend), take the hue from the theme token. */
.band[data-tint='accent'] { --band-hue: var(--mk-accent, #bf2f09); background: var(--mk-accent, #bf2f09); }
.band[data-tint='accent'] :is(.bandArt, .bandCanvas, .ghost) { mix-blend-mode: luminosity; }

.burst {
  position: absolute;
  top: 47.06%;
  left: calc(15% + (var(--at, 1) - 0.5) * 14%);
  z-index: 1;
  width: 12%;
  aspect-ratio: 1;
  border: 2px solid rgb(255 255 255 / 0.95);
  border-radius: 50%;
  opacity: 0;
  transform: translate(-50%, -50%);
  pointer-events: none;
}
.slots {
  position: absolute;
  inset: 0 15%;
  z-index: 2;
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  touch-action: pan-y;
}
.slot { position: relative; cursor: pointer; -webkit-tap-highlight-color: transparent; }
.radio {
  position: absolute;
  top: 47%;
  left: 50%;
  width: 1px;
  height: 1px;
  margin: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  appearance: none;
}
.ring {
  position: absolute;
  top: 47.06%;
  left: 50%;
  width: 84%;
  aspect-ratio: 1;
  border-radius: 50%;
  translate: -50% -50%;
  pointer-events: none;
}
/* Double ring: white then focus colour, visible on every part of the gradient and in both themes. */
.radio:focus-visible + .ring { box-shadow: 0 0 0 2px #fff, 0 0 0 4px var(--mk-focus, #1d4ed8); }

.result {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr) auto;
  align-items: center;
  gap: 0.25rem 0.875rem;
  min-width: 0;
}
.score {
  display: inline-flex;
  align-items: baseline;
  gap: 0.3rem;
  margin: 0;
  overflow: hidden;
  font-family: var(--mk-font-display, ui-sans-serif, system-ui, sans-serif);
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.04em;
}
.scoreNum {
  display: inline-block;
  min-width: 0.62em;
  font-size: clamp(2.25rem, 11cqi, 3rem);
  font-variant-numeric: tabular-nums;
  text-align: center;
}
.scoreOf { font-size: 0.9375rem; letter-spacing: 0; color: var(--mk-ink-muted, #5c5a52); }
.score[data-preview] .scoreNum { color: var(--mk-ink-muted, #5c5a52); }
.score[data-empty] .scoreNum { font-weight: 300; color: var(--mk-ink-muted, #5c5a52); }
.word { min-width: 0; margin: 0; font-size: 0.9375rem; font-weight: 550; line-height: 1.3; }
.tag {
  display: inline-block;
  margin-right: 0.5rem;
  padding: 0.125rem 0.375rem;
  border: 1px solid var(--mk-line-strong, #11110f);
  border-radius: var(--mk-radius-s, 4px);
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.625rem;
  font-weight: 500;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  vertical-align: 0.12em;
}
.textButton {
  min-height: 2.75rem;
  padding: 0 0.75rem;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: var(--mk-ink, #11110f);
  font: inherit;
  font-size: 0.875rem;
  font-weight: 600;
  text-decoration: underline;
  text-decoration-color: color-mix(in oklab, var(--mk-ink, #11110f) 40%, transparent);
  text-underline-offset: 0.25em;
  cursor: pointer;
  transition: background-color var(--mk-duration-fast, 160ms) var(--mk-ease-standard, ease);
}
.textButton:hover { background: color-mix(in oklab, var(--mk-ink, #11110f) 6%, transparent); }
.textButton:focus-visible { outline: 2px solid var(--mk-focus, #1d4ed8); outline-offset: 2px; }
.textButton[aria-disabled='true'] { cursor: default; color: var(--mk-ink-muted, #5c5a52); text-decoration-color: transparent; background: transparent; }

.breakdown {
  display: grid;
  gap: 0.55rem;
  min-width: 0;
  padding-top: 0.875rem;
  border-top: 1px dashed var(--mk-line, #11110f24);
}
.breakdownHead {
  display: flex;
  flex-wrap: wrap;
  justify-content: space-between;
  align-items: baseline;
  gap: 0.25rem 1rem;
  margin: 0;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-variant-numeric: tabular-nums;
  color: var(--mk-ink-muted, #5c5a52);
}
.breakdownMean strong { font-weight: 600; color: var(--mk-ink, #11110f); }
.bars { display: grid; gap: 0.3rem; margin: 0; padding: 0; list-style: none; }
.bar {
  display: grid;
  grid-template-columns: 1ch minmax(0, 1fr) 3ch;
  align-items: center;
  gap: 0.625rem;
  font-family: var(--mk-font-mono, ui-monospace, monospace);
  font-size: 0.6875rem;
  font-variant-numeric: tabular-nums;
  color: var(--mk-ink-muted, #5c5a52);
}
.barTrack {
  height: 0.375rem;
  overflow: hidden;
  border-radius: 999px;
  background: color-mix(in oklab, var(--mk-ink, #11110f) 8%, transparent);
}
.barFill {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: color-mix(in oklab, var(--mk-ink, #11110f) 42%, var(--mk-surface, #fbf9f4));
  transform-origin: 0 50%;
  transition:
    transform var(--rs-settle-ms, 560ms) var(--rs-settle, var(--mk-ease-emphasized, ease)),
    background-color var(--mk-duration-base, 240ms) var(--mk-ease-standard, ease);
}
.barCount { text-align: right; }
.bar[data-mine] { color: var(--mk-ink, #11110f); font-weight: 600; }
.bar[data-mine] .barFill { background: var(--mk-accent, #bf2f09); }

.credit {
  margin: clamp(0.875rem, 2.4cqi, 1.25rem) auto 0;
  max-width: 62rem;
  text-align: center;
  text-transform: uppercase;
  color: var(--mk-ink-muted, #5c5a52);
}
.srOnly {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}

/* ── Motion (full motion only) ────────────────────────────────────────── */
@media (prefers-reduced-motion: no-preference) {
  /* Entrance: the panel lands, then its rows follow in order. */
  .root:not([data-reduced]) .panel {
    animation: rs-lift var(--mk-duration-slow, 560ms) var(--mk-ease-emphasized, cubic-bezier(0.16, 1, 0.3, 1)) both;
    animation-delay: calc(var(--i, 0) * var(--mk-stagger-loose, 90ms));
  }
  .root:not([data-reduced]) .panel > :not(.srOnly) {
    animation: rs-rise var(--mk-duration-moderate, 360ms) var(--mk-ease-enter, cubic-bezier(0.05, 0.7, 0.1, 1)) both;
    animation-delay: calc(var(--i, 0) * var(--mk-stagger-loose, 90ms) + var(--mk-stagger-dramatic, 140ms) + var(--row, 0) * var(--mk-stagger-base, 48ms));
  }
  .root:not([data-reduced]) .panel > :nth-child(2) { --row: 1; }
  .root:not([data-reduced]) .panel > :nth-child(3) { --row: 2; }
  .root:not([data-reduced]) .panel > :nth-child(4) { --row: 3; }
  .root:not([data-reduced]) .panel > :nth-child(5) { --row: 4; }
  /* The score ticks to its new value. */
  .root:not([data-reduced]) .scoreNum { animation: rs-tick var(--mk-duration-moderate, 360ms) var(--mk-ease-emphasized, ease) both; }
  /* The equaliser bounces while Birb dances. */
  .root:not([data-reduced]) .eq[data-on] i { animation: rs-eq var(--mk-duration-moderate, 360ms) var(--mk-ease-inOut, ease-in-out) infinite alternate; }
  .root:not([data-reduced]) .eq[data-on] i:nth-child(2) { animation-delay: calc(var(--mk-duration-moderate, 360ms) * -0.66); }
  .root:not([data-reduced]) .eq[data-on] i:nth-child(3) { animation-delay: calc(var(--mk-duration-moderate, 360ms) * -0.33); }
}
@keyframes rs-lift { from { opacity: 0; transform: translateY(18px) scale(0.985); } }
@keyframes rs-rise { from { opacity: 0; transform: translateY(10px); } }
@keyframes rs-tick { from { opacity: 0; transform: translateY(42%); } }
@keyframes rs-eq { from { transform: scaleY(0.3); } to { transform: scaleY(1); } }

.root[data-reduced] :is(.button, .playButton, .lookIcon, .dot, .wall, .bandArt, .textButton, .barFill) { transition-duration: 0ms; }
.root[data-reduced] :is(.button, .playButton):active { transform: none; }
@media (prefers-reduced-motion: reduce) {
  :is(.button, .playButton, .lookIcon, .wall, .barFill) { transition-duration: 0ms; }
  :is(.button, .playButton):active { transform: none; }
}
